package api

import (
	"fmt"
	"math"
	"net/http"
	"regexp"
	"strings"
	"unicode/utf8"

	"github.com/GeoCrew-Dev/GeoCrew-Server/internal/store"
)

// ids are generated by clients so that a retried post is not stored twice.
var commentID = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)

type addCommentReq struct {
	ID        string    `json:"id"`
	FeatureID string    `json:"feature_id"`
	Body      string    `json:"body"`
	At        []float64 `json:"at"`
}

func (q addCommentReq) validate() (store.Comment, error) {
	c := store.Comment{ID: q.ID, FeatureID: q.FeatureID, Body: strings.TrimSpace(q.Body), At: q.At}
	switch {
	case !commentID.MatchString(c.ID):
		return c, fmt.Errorf("id must be 1-64 letters, digits, '.', '_' or '-'")
	case c.FeatureID != "" && len(c.FeatureID) > 64:
		return c, fmt.Errorf("feature_id must be at most 64 characters")
	case c.Body == "" || !utf8.ValidString(c.Body):
		return c, fmt.Errorf("body must be non-empty UTF-8 text")
	case utf8.RuneCountInString(c.Body) > store.MaxCommentRunes:
		return c, fmt.Errorf("body must be at most %d characters", store.MaxCommentRunes)
	}
	if c.At != nil {
		if len(c.At) != 2 || !finite(c.At...) || math.Abs(c.At[0]) > 180 || math.Abs(c.At[1]) > 90 {
			return c, fmt.Errorf("at must be [longitude, latitude]")
		}
	}
	return c, nil
}

func finite(vs ...float64) bool {
	for _, v := range vs {
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return false
		}
	}
	return true
}

func (s *Server) addComment(w http.ResponseWriter, r *http.Request) {
	var req addCommentReq
	if !decode(w, r, &req) {
		return
	}
	c, err := req.validate()
	if err != nil {
		writeErr(w, http.StatusBadRequest, "invalid_comment", err.Error())
		return
	}
	ws := r.PathValue("ws")
	out, err := s.Store.AddComment(r.Context(), ws, member(r).ID, c)
	if err != nil {
		s.fail(w, r, err)
		return
	}
	s.Hub.CommentsChanged(ws, out.Seq)
	s.notifyComment(ws, out)
	writeJSON(w, http.StatusOK, out)
}

type commentsResp struct {
	Comments []store.Comment `json:"comments"`
	Seq      int64           `json:"seq"`
	More     bool            `json:"more"`
}

func (s *Server) comments(w http.ResponseWriter, r *http.Request) {
	since, limit, ok := page(w, r, s.MaxPullFeatures)
	if !ok {
		return
	}
	cs, more, err := s.Store.Comments(r.Context(), r.PathValue("ws"), since, limit)
	if err != nil {
		s.fail(w, r, err)
		return
	}
	resp := commentsResp{Comments: cs, Seq: since, More: more}
	if n := len(cs); n > 0 {
		resp.Seq = cs[n-1].Seq
	}
	writeJSON(w, http.StatusOK, resp)
}

func (s *Server) deleteComment(w http.ResponseWriter, r *http.Request) {
	m := member(r)
	ws := r.PathValue("ws")
	c, err := s.Store.DeleteComment(r.Context(), ws, r.PathValue("comment"), m.ID, m.Role == store.RoleLeader)
	if err != nil {
		s.fail(w, r, err)
		return
	}
	s.Hub.CommentsChanged(ws, c.Seq)
	w.WriteHeader(http.StatusNoContent)
}
